package com.wedo.backend.task.controller;
import com.wedo.backend.security.AuthenticatedUserPrincipal; import com.wedo.backend.task.dto.*; import com.wedo.backend.task.entity.TaskStatus; import com.wedo.backend.task.service.TaskService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class TaskController {private final TaskService service;public TaskController(TaskService service){this.service=service;}@PostMapping("/activities/{activityId}/tasks") public ResponseEntity<TaskResponse> create(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID activityId,@Valid @RequestBody CreateTaskRequest r){return ResponseEntity.status(201).body(service.create(activityId,p.userId(),r));}@GetMapping("/activities/{activityId}/tasks") public List<TaskResponse> list(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID activityId,@RequestParam(required=false) TaskStatus status,@RequestParam(defaultValue="false") boolean assignedToMe){return service.list(activityId,p.userId(),status,assignedToMe);}@GetMapping("/tasks/{taskId}") public TaskResponse get(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID taskId){return service.get(taskId,p.userId());}@PatchMapping("/tasks/{taskId}") public TaskResponse update(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID taskId,@Valid @RequestBody UpdateTaskRequest r){return service.update(taskId,p.userId(),r);}@PutMapping("/tasks/{taskId}/status") public TaskResponse status(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID taskId,@Valid @RequestBody UpdateTaskStatusRequest r){return service.changeStatus(taskId,p.userId(),r);}@PostMapping("/tasks/{taskId}/claim") public TaskResponse claim(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID taskId){return service.claim(taskId,p.userId());}@DeleteMapping("/tasks/{taskId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID taskId){service.delete(taskId,p.userId());}}
